/* @autogenerated */
package net.civeira.phylax.features.oauth.common;

import io.quarkus.scheduler.Scheduled;
import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.features.oauth.mfa.infrastructure.driven.OAuthCleanupService;

/**
 * Quarkus scheduler that periodically removes expired OAuth records from the database.
 *
 * <p>
 * Cron expressions can be overridden per environment:
 * <ul>
 * <li>{@code oauth.cleanup.temporal-codes.cron} — default {@code 0 0 3 * * ?} (03:00)</li>
 * <li>{@code oauth.cleanup.sessions.cron} — default {@code 0 30 3 * * ?} (03:30)</li>
 * </ul>
 * </p>
 */
@ApplicationScoped
@RequiredArgsConstructor
@Slf4j
public class OAuthExpiredRecordsCleaner {

  private final OAuthCleanupService cleanupService;

  /**
   * Deletes expired rows from {@code _oauth_temporal_codes}.
   *
   * <p>
   * Runs daily at 03:00 by default. Exceptions are caught and logged so the scheduler thread is
   * never interrupted.
   * </p>
   */
  @Scheduled(cron = "${oauth.cleanup.temporal-codes.cron:0 0 3 * * ?}")
  public void cleanExpiredTemporalCodes() {
    log.debug("Running OAuth expired temporal codes cleanup");
    try {
      cleanupService.deleteExpiredTemporalCodes();
    } catch (Exception e) {
      log.error("OAuth temporal codes cleanup failed", e);
    }
  }

  /**
   * Deletes expired rows from {@code _oauth_sessions}.
   *
   * <p>
   * Runs daily at 03:30 by default. Exceptions are caught and logged so the scheduler thread is
   * never interrupted.
   * </p>
   */
  @Scheduled(cron = "${oauth.cleanup.sessions.cron:0 30 3 * * ?}")
  public void cleanExpiredSessions() {
    log.debug("Running OAuth expired sessions cleanup");
    try {
      cleanupService.deleteExpiredSessions();
    } catch (Exception e) {
      log.error("OAuth sessions cleanup failed", e);
    }
  }
}
